    data?: Uint8Array | Buffer;
    /** Base64 image (no data-URL prefix) — preferred on React Native. */
    base64?: string;
    /** Temporary file URI (React Native `react-native-view-shot` tmpfile). */
    tmpUri?: string;
    platform?: 'web' | 'react-native';
    viewport?: {
        width?: number;
        height?: number;
        scale?: number;
    };
